def multiplicative_order(a, n):
    phi = n - 1 # Since n is prime
    factors = set()
    d = phi
    i = 2
    while i * i <= d:
        if d % i == 0:
            factors.add(i)
            while d % i == 0:
                d //= i
        i += 1

    for p in factors:
        exp = phi // p
        while pow(a, exp, n) == 1:
            exp //= p
    return pow(a, exp, n)

# Find the order of 22 mod 43 (phi=42). We found 14 earlier, let's confirm.
print(f"Order of 22 mod 43: {multiplicative_order(22, 43)}")

